import fs from 'node:fs/promises';
import path from 'node:path';
import {localizePages} from './localize.mjs';
const renderedPages=new Map();
const data=JSON.parse(await fs.readFile('content/content.json','utf8'));
const maps=JSON.parse(await fs.readFile('content/maps-photos.json','utf8')).filter(x=>x.local);
const OUT='dist';
const mapUrl='https://www.google.com/maps/place/Loft+Pet+House/@41.0098302,29.0371677,17z/data=!3m1!4b1!4m6!3m5!1s0x14cab804068be33b:0xdad18209ed601518!8m2!3d41.0098302!4d29.0397426!16s%2Fg%2F11f3p167lm';
const phone='0532 529 01 76',tel='tel:+905325290176',wa='https://wa.me/905325290176';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const svg=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${{
 arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',
 paw:'<ellipse cx="7" cy="7" rx="2" ry="3" transform="rotate(-20 7 7)"/><ellipse cx="17" cy="7" rx="2" ry="3" transform="rotate(20 17 7)"/><ellipse cx="3" cy="12" rx="1.8" ry="2.4" transform="rotate(-30 3 12)"/><ellipse cx="21" cy="12" rx="1.8" ry="2.4" transform="rotate(30 21 12)"/><path d="M6 18c0-3 3-7 6-7s6 4 6 7c0 4-4 1-6 1s-6 3-6-1Z"/>',
 house:'<path d="m2 11 10-8 10 8M5 9v12h14V9M9 21v-7h6v7"/>',heart:'<path d="M12 21S2 15 2 8a5 5 0 0 1 10-1 5 5 0 0 1 10 1c0 7-10 13-10 13Z"/>',
 scissors:'<circle cx="5" cy="6" r="3"/><circle cx="5" cy="18" r="3"/><path d="m7 8 14 13M7 16 21 3"/>',bag:'<path d="M5 7h14l2 14H3L5 7ZM8 7V5a4 4 0 0 1 8 0v2"/>',medical:'<path d="M8 3h8v5h5v8h-5v5H8v-5H3V8h5Z"/>',training:'<path d="m2 9 10-6 10 6-10 6L2 9ZM6 12v6c4 3 8 3 12 0v-6M22 9v8"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',phone:'<path d="m5 2 4 5-3 3a17 17 0 0 0 8 8l3-3 5 4-2 3C10 23 1 14 2 4l3-2Z"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 11h18M7 15h3M14 15h3"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z"/>',check:'<path d="m5 12 4 4L19 6"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 5 10 8L22 5"/>'}[name]||''}</svg>`;
const serviceMeta={
1:{icon:'house',summary:'Minik dostunuz için ev konforunda konaklama ve sosyalleşme alanları.',short:'Pet Hotel'},
4:{icon:'scissors',summary:'Banyo, makas ve model tıraşı. Sevgiyle, sabırla, anestezisiz bakım.',short:'Bakım & Kuaför'},
3:{icon:'bag',summary:'Mama, oyuncak ve aksesuarlarla küçük dostunuzun ihtiyaçları bir arada.',short:'Pet Shop'},
2:{icon:'medical',summary:'Bizimle konaklayan dostlarımız için rutin sağlık kontrolü ve bakım.',short:'Veteriner Desteği'},
5:{icon:'training',summary:'Birlikte yaşamı kolaylaştıran eğitim hizmetimiz hakkında bilgi alın.',short:'Eğitim'},
6:{icon:'heart',summary:'Bir yuva bekleyen dostlarımızla yeni ailelerini buluşturmaya destek.',short:'Ücretsiz Sahiplendirme'}};
const services=[1,4,3,2,5,6].map(id=>({...data.services.find(s=>s.path.includes('/'+id+'/')),...serviceMeta[id],id}));
const navItems=[['hakkimizda/','Hakkımızda'],['hizmetlerimiz/','Hizmetlerimiz'],['galeri/','Galeri'],['sikca-sorulan-sorular/','S.S.S.'],['iletisim/','İletişim']];
const paras=a=>a.map(p=>`<p>${esc(p)}</p>`).join('');
let prefix='';
const link=p=>prefix+(p?p.replace(/^\//,'').replace(/\/$/,'')+'/index.html':'index.html');
const asset=p=>prefix+p;
const button=(text,url,kind='',icon='arrow')=>`<a class="button ${kind}" href="${esc(url)}">${text}${svg(icon)}</a>`;
function brand(){return `<a class="brand" href="${link('')}" aria-label="Loft Pet House ana sayfa"><img src="${asset('assets/loft-pet-house-logo.jpg')}" width="68" height="68" alt="Loft Pet House — Hotel, Barber, Shop"><span><strong>LOFT</strong><small>PET HOUSE</small></span></a>`;}
function head(title,desc){return `<section class="page-head"><div class="wrap"><nav class="breadcrumbs" aria-label="İçerik yolu"><a href="${link('')}">Ana sayfa</a><span>/</span><span>${esc(title)}</span></nav><div class="eyebrow">LOFT PET HOUSE</div><h1>${esc(title)}</h1>${desc?`<p>${desc}</p>`:''}</div></section>`;}
function cta(){return `<section class="section wrap"><div class="cta"><div><h2>Minik dostunuza bir tatil.</h2><p>Küçük dostlarımızı çok seviyoruz. Onlarla tanışmak için sabırsızlanıyoruz.</p></div>${button('Birlikte planlayalım',link('rezervasyon/'),'light')}</div></section>`;}
function card(s,i){return `<a class="service-card ${i===0?'featured':''}" href="${link(s.path)}"><div class="icon">${svg(s.icon)}</div><span class="number">0${i+1}</span><h3>${s.short}</h3><p>${s.summary}</p><div class="card-bottom"><span>Yakından tanıyın</span>${svg('arrow')}</div></a>`;}
function serviceGrid(){return `<div class="service-grid">${services.map(card).join('')}</div>`;}
function faq(items){return items.map(f=>`<details><summary>${esc(f.q)}</summary><div class="answer">${paras(f.a)}</div></details>`).join('');}
// The owner's current hours and contact details supersede the archived operational details.
const faqCurrent=data.faq.map((f,i)=> i===1?{q:'Hangi saatler arasında hizmet veriyorsunuz?',a:['Haftanın her günü 09:00–18:30 saatleri arasında hizmet veriyoruz. Resmî tatillerde çalışma saatleri farklılık gösterebilir.','Konaklama giriş-çıkış saati, teslim alma ve ücretlendirme koşulları için lütfen 0532 529 01 76 numarasından bizimle iletişime geçin.']}:i===6?{q:f.q,a:['Dostunuzu merak ettiğinizde bize ulaşabilirsiniz. Görüntülü görüşme ve konaklama süresince bilgilendirme seçeneklerini birlikte planlayalım.',`Tel No: ${phone}`]}:f);
function photoGrid(limit){const captions={1:'Koşuyolu’ndaki evimiz',2:'Bakım sonrası küçük bir mola',3:'Mutlu patiler, özenli bakım',5:'Kedi dostlarımızın bakım zamanı',6:'Loft’un minik misafirleri',7:'Minik dostlarımızla bir gün',8:'Sevgiyle ilgileniyoruz',9:'Birlikte güzel vakit geçiriyoruz',10:'Her patiye ayrı ilgi'};return `<div class="photo-grid">${maps.slice(0,limit||maps.length).map(p=>`<button class="gallery-photo" data-photo="${asset(p.local)}" data-caption="${captions[p.n]||'Loft Pet House'}" aria-label="${captions[p.n]||'Loft Pet House'} fotoğrafını büyüt"><img src="${asset(p.local)}" alt="${captions[p.n]||'Loft Pet House misafiri'}" loading="lazy" width="500" height="570"><span>${captions[p.n]||'Loft Pet House'} <b>↗</b></span></button>`).join('')}</div>`;}
function form(reservation=false){return `<div class="form-panel"><h2>${reservation?'Mutlu bir tatil planlayalım.':'Görüşlerinize değer veriyoruz.'}</h2><p>${reservation?'Tarih ve hizmet tercihinizi bize iletin. Müsaitliği birlikte netleştirelim.':'Mesajınızı hazırlayın; e-posta uygulamanızdan bize iletin.'}</p><form id="contact-form"><p class="form-unavailable">Form şu anda kullanılamıyor. <a href="${tel}">Bizi arayın</a> veya <a href="mailto:info@loftpethouse.com">e-posta gönderin</a>.</p><fieldset class="form-fields" disabled><div class="form-grid"><label class="full">Adınız soyadınız *<input name="Ad soyad" autocomplete="name" required maxlength="100"></label><label class="mobile-full">Telefonunuz *<input name="Telefon" type="tel" autocomplete="tel" required maxlength="30"></label><label class="mobile-full">E-posta adresiniz<input name="E-posta" type="email" autocomplete="email" maxlength="150"></label>${reservation?`<label class="mobile-full">Hizmet *<select name="Hizmet" required><option value="">Hizmet seçin</option>${services.map(s=>`<option>${s.title}</option>`).join('')}</select></label><label class="mobile-full">Tercih ettiğiniz tarih *<input name="Tarih" type="date" required></label>`:`<label class="full">Konu<input name="Konu" maxlength="120"></label>`}<label class="full">Mesajınız *<textarea name="Mesaj" required maxlength="3000" placeholder="${reservation?'Dostunuzdan ve ihtiyaçlarından biraz bahseder misiniz?':'Size nasıl yardımcı olabiliriz?'}"></textarea></label></div><button type="submit" class="button">E-posta taslağını hazırla ${svg('arrow')}</button><p class="form-status">Bu form rezervasyon onayı oluşturmaz. Mesajınız, e-posta uygulamanızda gönderdiğinizde bize ulaşır.</p><div class="draft-result" hidden><p>Taslağınız hazır. E-posta uygulamanızda kontrol edip gönderin.</p><div class="actions"><a class="button" href="mailto:info@loftpethouse.com">E-posta uygulamasını aç ${svg('mail')}</a><button type="button" class="button outline draft-copy">Mesajı kopyala</button></div><div class="form-status" role="status" aria-live="polite"></div></div></fieldset></form></div>`;}
function contact(reservation=false){return `${head(reservation?'Rezervasyon & bilgi':'Bize ulaşın',reservation?'Ailenizin en küçüğü için güzel bir konaklamanın ilk adımı.':'Koşuyolu’ndaki evimize bekleriz.')}<section class="section wrap contact-grid"><div><div class="contact-details"><div class="contact-item"><small>Telefon</small><a href="${tel}">${phone}</a><p>Konaklama, bakım ve müsaitlik hakkında.</p></div><div class="contact-item"><small>Adresimiz</small><address>Koşuyolu, İsmailpaşa Sk. No:32<br>34718 Kadıköy / İstanbul</address><a class="text-link" href="${mapUrl}" target="_blank" rel="noopener" style="font-size:12px;margin-top:15px">Google Maps’te yol tarifi ${svg('arrow')}</a></div><div class="contact-item"><small>Çalışma saatleri</small><p><strong>Her gün · 09:00–18:30</strong></p><p>Pazartesi–Pazar. Resmî tatillerde saatler farklılık gösterebilir.</p></div><div class="contact-item"><small>E-posta</small><a href="mailto:info@loftpethouse.com" style="font-size:16px">info@loftpethouse.com</a></div></div><div class="actions">${button('WhatsApp’tan yazın',wa,'outline')}${button('Hemen arayın',tel,'','phone')}</div></div>${form(reservation)}</section>`;}
async function page(route,title,bodyFn,description){
 const parts=route.split('/').filter(Boolean);prefix='../'.repeat(parts.length);
 const body=bodyFn();
 const schema={'@context':'https://schema.org','@type':'LocalBusiness',name:'Loft Pet House',telephone:'+90 532 529 01 76',email:'info@loftpethouse.com',address:{'@type':'PostalAddress',streetAddress:'Koşuyolu, İsmailpaşa Sk. No:32',addressLocality:'Kadıköy',addressRegion:'İstanbul',postalCode:'34718',addressCountry:'TR'},geo:{'@type':'GeoCoordinates',latitude:41.0098302,longitude:29.0397426},openingHoursSpecification:[{'@type':'OpeningHoursSpecification',dayOfWeek:['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'],opens:'09:00',closes:'18:30'}],hasMap:mapUrl};
 const html=`<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} | Loft Pet House</title><meta name="description" content="${esc(description||'Koşuyolu’nda ev konforunda kedi ve köpek oteli, bakım ve kuaför hizmetleri. Loft Pet House: 0532 529 01 76. Her gün 09:00–18:30.')}"/><meta name="theme-color" content="#171717"><link rel="icon" href="${asset('favicon.ico')}" sizes="any"><link rel="apple-touch-icon" href="${asset('assets/apple-touch-icon.png')}"><link rel="stylesheet" href="${asset('style.css')}"><script src="${asset('app.js')}" defer></script><script type="application/ld+json">${JSON.stringify(schema)}</script></head><body id="top"><a class="skip" href="#main">İçeriğe geç</a><div class="topbar"><div class="wrap"><span>${svg('pin')}KOŞUYOLU, İSTANBUL · MİNİK DOSTLARINIZIN İKİNCİ EVİ</span><span>HER GÜN 09:00–18:30 <span>·</span> <a href="${tel}">${phone}</a></span></div></div><header class="header"><div class="wrap">${brand()}<button class="menu-toggle" aria-label="Menüyü aç" aria-controls="main-nav" aria-expanded="false">${svg('menu')}</button><nav id="main-nav" class="nav" aria-label="Ana menü">${navItems.map(([p,t])=>`<a href="${link(p)}" ${route===p?'aria-current="page"':''}>${t}</a>`).join('')}</nav>${button('Rezervasyon',link('rezervasyon/'),'header-cta','arrow')}</div></header><main id="main">${body}</main><footer class="footer"><div class="wrap"><div class="footer-grid"><div>${brand()}<p>Hayatı birlikte paylaşıyoruz.<br>Minik dostlarınız bize emanet.</p><div class="social"><a href="https://www.instagram.com/loftpethouse/" target="_blank" rel="noopener">Instagram ↗</a><a href="https://www.facebook.com/loftpethouse/" target="_blank" rel="noopener">Facebook ↗</a></div></div><div><h3>Bir merhaba deyin</h3><address>Koşuyolu, İsmailpaşa Sk. No:32<br>34718 Kadıköy / İstanbul<br><a href="${tel}">${phone}</a><br><a href="mailto:info@loftpethouse.com">info@loftpethouse.com</a><br>Her gün · 09:00–18:30</address></div><div><h3>Loft’u keşfedin</h3><div class="footer-links">${navItems.map(([p,t])=>`<a href="${link(p)}">${t}</a>`).join('')}<a href="${link('rezervasyon/')}">Rezervasyon</a><a href="${mapUrl}" target="_blank" rel="noopener">Yol tarifi ↗</a></div></div></div><div class="footer-bottom"><span>© 2026 Loft Pet House. Sevgiyle, birlikte.</span><a class="to-top" href="#top">Başa dön ↑</a></div></div></footer><div class="mobile-bottom">${button('Hemen ara',tel,'outline','phone')}${button('Rezervasyon',link('rezervasyon/'),'','calendar')}</div><dialog class="lightbox" aria-label="Fotoğraf görüntüleyici"><button class="lightbox-close" aria-label="Fotoğrafı kapat">×</button><img alt=""><p></p></dialog></body></html>`;
 const dir=path.join(OUT,route);await fs.mkdir(dir,{recursive:true});await fs.writeFile(path.join(dir,'index.html'),html);
 renderedPages.set((route+'index.html').replaceAll('\\','/'),html);
}
await page('','Kedi & Köpek Oteli',()=>`<div class="wrap"><section class="hero"><div><div class="eyebrow">BİR OTELDEN ÇOK, İKİNCİ BİR EV</div><h1>Evinizdeki sıcaklık,<br><em>doğadaki huzur.</em></h1><p>Ailenizin en küçüğü emin ellerde. Koşuyolu’ndaki evimizde kedi ve köpek dostlarımızı sevgiyle ağırlıyoruz.</p><div class="actions">${button('Yerini birlikte planlayalım',link('rezervasyon/'))}<a class="text-link" href="${link('hizmetlerimiz/')}">Hizmetlerimiz ${svg('arrow')}</a></div><div class="hero-note">${svg('heart')}2016’dan beri, minik dostlarımızla yan yana.</div></div><div class="hero-photo"><img src="${asset('assets/hero.webp')}" alt="Yeşillikler içinde yan yana uzanan bir kedi ve köpek" width="900" height="700" fetchpriority="high"><div class="stamp"><span>SEVGİYLE</span>${svg('paw')}<span>BİRLİKTE</span></div><div class="photo-label">${svg('house')}<span><strong>Küçük dostlara, kocaman bir yuva.</strong>Hotel · Barber · Shop</span></div></div></section><div class="benefits">${[['house','Ev konforunda konaklama','Kedi ve köpek dostlarımız için'],['scissors','Özenli bakım & kuaför','Sabırla ve sevgiyle'],['medical','Veteriner hekim desteği','Konaklayan dostlarımıza'],['pin','Koşuyolu’nun kalbinde','Kolay ulaşım, sıcak bir karşılama']].map(([i,t,s])=>`<div class="benefit">${svg(i)}<span><strong>${t}</strong><small>${s}</small></span></div>`).join('')}</div></div><section class="section wrap"><div class="section-head"><div><div class="eyebrow">ONLAR İÇİN DÜŞÜNDÜK</div><h2>Dostlarınız için<br>her şey Loft’ta.</h2></div><p>Konaklamadan bakıma, oyundan yeni dostluklara… Küçük dostunuzun ihtiyaçları için buradayız.</p></div>${serviceGrid()}</section><section class="section wrap story"><div class="story-art"><img src="${asset('assets/maps-1.webp')}" alt="Loft Pet House Koşuyolu binası ve bahçe girişi" loading="lazy" width="650" height="450"><span class="location-label">KOŞUYOLU’NDAKİ EVİMİZ</span></div><div><div class="eyebrow">BİZİM HİKÂYEMİZ</div><h2>Hayatı birlikte<br>paylaşıyoruz.</h2><p>2016 yılında, minik dostlarımızın evlerinden uzakta oldukları her dakikayı mutlulukla geçirmelerini sağlamak için kollarımızı sevgiyle sıvadık.</p><p>Koşuyolu’ndaki şirin villamızda, en sıkı dostlarımız için ikinci bir yuva kurduk.</p><a class="text-link" href="${link('hakkimizda/')}">Bizi yakından tanıyın ${svg('arrow')}</a></div></section><section class="section wrap"><div class="section-head"><div><div class="eyebrow">LOFT’TAN KARELER</div><h2>Mutlu patiler, güzel anılar.</h2></div><a class="text-link" href="${link('galeri/')}">Tüm fotoğraflar ${svg('arrow')}</a></div>${photoGrid(3)}</section><section class="section faq-home"><div class="wrap faq-layout"><div class="faq-intro"><div class="eyebrow">AKLINIZA TAKILANLAR</div><h2>Gözünüz<br>arkada kalmasın.</h2><p>Küçük dostunuzun konaklamasından önce merak ettiklerinizi yanıtlıyoruz.</p><a class="text-link" href="${link('sikca-sorulan-sorular/')}">Tüm sorular ${svg('arrow')}</a></div><div>${faq([faqCurrent[2],faqCurrent[4],faqCurrent[1]])}</div></div></section><section class="section wrap"><a class="maps-review" href="${mapUrl}" target="_blank" rel="noopener"><span class="review-score">4,6 <span>★★★★★</span></span><span><strong>Birlikte büyüyen güzel bir aile.</strong><small>Google Maps’te 191 değerlendirme · 27 Ekim 2026</small></span><span class="review-link">Yorumları okuyun ${svg('arrow')}</span></a></section>${cta()}`);
await page('hizmetlerimiz/','Hizmetlerimiz',()=>`${head('Dostlarınız için her şey Loft’ta.','Minik dostlarımıza sizin kadar iyi bakıyoruz. Sıkı dostluklar kuruyoruz.')}<section class="section wrap">${serviceGrid()}</section>${cta()}`);
await page('hakkimizda/','Hakkımızda',()=>`${head('Onlar Mutlu, Biz Mutlu','Minik dostlarınız bize emanet!')}<section class="section wrap"><div class="about-full"><div class="prose">${paras([data.about[0]])}</div><div class="story-art"><img src="${asset('assets/maps-1.webp')}" alt="Loft Pet House’un Koşuyolu’ndaki giriş kapısı" width="650" height="450"><span class="location-label">2016’DAN BERİ, SEVGİYLE.</span></div></div><div class="prose" style="margin-top:40px">${paras([data.about[1]])}</div><blockquote class="about-quote">“Sizin yerinizi almayacağız<br>ama sizi de aratmayacağız.”</blockquote></section>${cta()}`);
for(const s of services){await page(s.path.replace(/^\//,'')+'/',s.title,()=>`${head(s.title,s.summary)}<section class="section wrap article-layout"><article class="prose">${paras(s.paragraphs)}</article><aside class="aside-box"><h2>Birlikte planlayalım.</h2><p>Hizmetlerimiz ve müsaitlik hakkında bilgi almak için bize ulaşın.</p><a class="phone" href="${tel}">${phone}</a>${button('Bilgi & rezervasyon',link('rezervasyon/'))}</aside></section><section class="section wrap other-services"><h2>Diğer hizmetlerimiz</h2><div class="service-grid">${services.filter(x=>x.id!==s.id).map(card).join('')}</div></section>`);}
await page('sikca-sorulan-sorular/','Sıkça Sorulan Sorular',()=>`${head('Gözünüz arkada kalmasın.','Sizin yerinizi alamayız ama sizi de aratmayız.')}<section class="section wrap"><div class="all-faq">${faq(faqCurrent)}<p class="note">Konaklama ve hizmet ayrıntılarını rezervasyon öncesinde bizimle görüşebilirsiniz: <a href="${tel}">${phone}</a>.</p></div></section>${cta()}`);
await page('galeri/','Galeri',()=>`${head('Loft’tan güzel anılar.','Küçük dostlarımız, keyifli bakım anları ve Koşuyolu’ndaki evimiz.')}<section class="section wrap">${photoGrid()}<p class="photo-source">Loft Pet House’un Google Maps işletme profilinden paylaştığı fotoğraflar.</p><div class="gallery-note"><div><h2>Daha çok pati, daha çok anı.</h2><p>Güncel fotoğraflarımız ve minik dostlarımız için bizi takip edin.</p></div>${button('Google Maps’te keşfedin',mapUrl,'outline')}</div></section>${cta()}`);
await page('iletisim/','İletişim',()=>contact(false));
await page('rezervasyon/','Rezervasyon',()=>contact(true));
await fs.writeFile(path.join(OUT,'robots.txt'),'User-agent: *\nAllow: /\n');
await fs.copyFile('theme.css',path.join(OUT,'theme.css'));
await localizePages(renderedPages,OUT);
